ALTER TABLE APPID.PATH_OVERRIDE_MEMBER_LINK ADD CONSTRAINT PATH_OVERRIDE_MEMBER_LINK_CHK1 CHECK (
        INTERFACE_ID IS NOT NULL OR LINK_CLASS_ID IS NOT NULL
    );
ALTER TABLE CERTS.CERTIFICATE_USAGE ADD CONSTRAINT CERTIFICATE_USAGE_CK1 CHECK (COMPANY_ID IS NOT NULL OR GROUP_ID IS NOT NULL OR SERVICE_ID IS NOT NULL OR HOST_ID IS NOT NULL);
ALTER TABLE CERTS.SAN ADD CONSTRAINT SAN_CK1 CHECK (CERTIFICATE_ID IS NOT NULL OR CSR_ID IS NOT NULL);
ALTER TABLE CERTS.SAN ADD CONSTRAINT SAN_CK2 CHECK (CERTIFICATE_ID IS NULL OR CSR_ID IS NULL);
ALTER TABLE FW.IP_ADDRESS ADD CONSTRAINT IP_ADDRESS_CK1 CHECK (ip_address >= 0);
ALTER TABLE FW.RULE ADD CONSTRAINT RULE_CK1 CHECK (APP_GROUP_ID IS NULL OR (APP_GROUP_ID IS NOT NULL AND DST_IP_GROUP_ID IS NULL AND SERVICE_GROUP_ID IS NULL));
ALTER TABLE FW.SUB_SECTION ADD CONSTRAINT C_SUB_SECTION_1 CHECK (SOURCE_SERVICE_ID IS NOT NULL OR SUB_SECTION_TYPE_ID = 1);
ALTER TABLE GUMA2.PATTERN ADD CONSTRAINT PATTERN_CK1 CHECK (negate IN (0, 1));
ALTER TABLE GUMA2.PATTERN ADD CONSTRAINT PATTERN_CK2 CHECK (ignore_case IN (0, 1));
ALTER TABLE GUMA2.SIGNATURE ADD CONSTRAINT SIGNATURE_CK1 CHECK (action IN ('I', 'P', 'T'));
ALTER TABLE MC.AVAILABILITY_REPORT ADD CONSTRAINT AVAILABILITY_REPORT_CK1 CHECK (MONTH >= 1 AND 12 >= MONTH);
ALTER TABLE MC.AVAILABILITY_REPORT ADD CONSTRAINT AVAILABILITY_REPORT_CK2 CHECK (SERVICE_ID is not null OR DELETED_SERVICE_ID is not null);
ALTER TABLE MC.CONN_SLA_TARGET ADD CONSTRAINT CONN_SLA_TARGET_CK1 CHECK (TARGET >= 1000 AND 99999 >= TARGET);
ALTER TABLE MC.ISP_AVAILABILITY_REPORT ADD CONSTRAINT ISP_AVAILABILITY_REPORT_CK1 CHECK (MONTH >= 1 AND 12 >= MONTH);
ALTER TABLE MSS.CVPN_PROXY_CONFIG ADD CONSTRAINT CVPN_PROXY_CONFIG_CK1 CHECK ((ADDRESS IS NOT NULL AND PORT IS NOT NULL) OR PAC_URL IS NOT NULL);
ALTER TABLE MSS.NETWORK ADD CONSTRAINT NETWORK_CK1 CHECK (netmask < 33) DEFERRABLE;
ALTER TABLE MSS.OPENVPN_INTERFACE ADD CONSTRAINT C_OPENVPN_INTERFACE_NAME CHECK (NAME LIKE 'mvpn_') DEFERRABLE;
ALTER TABLE MSS.SPEED_TESTS ADD CONSTRAINT CHK_SPEED_TESTS_ADJUST_QOS CHECK (ADJUST_QOS IN (0, 1));
ALTER TABLE MSS.SPEED_TESTS ADD CONSTRAINT CHK_SPEED_TESTS_BW_DOWN CHECK (BANDWIDTH_DOWN >= 0);
ALTER TABLE MSS.SPEED_TESTS ADD CONSTRAINT CHK_SPEED_TESTS_BW_UP CHECK (BANDWIDTH_UP >= 0);
ALTER TABLE MSS.SPEED_TESTS ADD CONSTRAINT CHK_SPEED_TESTS_TARGET CHECK (
        AZURE_REGION IS NOT NULL OR 
        TUNNEL_ID IS NOT NULL OR 
        IPERF_HOST IS NOT NULL
    );
ALTER TABLE NIDS.MDR_SIGNATURE_GROUP_MEMBER ADD CONSTRAINT MDR_SIGNATURE_GROUP_MEMBER_C1 CHECK ((MDR_MEMBER_SIGNATURE_GROUP_ID IS NOT NULL AND MDR_SIGNATURE_ID IS NULL) OR
        (MDR_MEMBER_SIGNATURE_GROUP_ID IS NULL AND MDR_SIGNATURE_ID IS NOT NULL)) DEFERRABLE;
ALTER TABLE NIDS.NIDS_IP_NETWORK ADD CONSTRAINT NIDS_IP_NETWORK_CK1 CHECK (netmask < 33) DEFERRABLE;
ALTER TABLE PRX.PRX_POLICY_GROUP_ENTRY ADD CONSTRAINT PRX_POLICY_GROUP_ENTRY_C1 CHECK ((IP4_ADDRESS IS NOT NULL AND NETMASK IS NOT NULL AND IP6_ADDRESS1 IS NULL AND IP6_ADDRESS2 IS NULL AND AUTHENTICATED_GROUP_NAME IS NULL) OR
                   (IP6_ADDRESS1 IS NOT NULL AND IP6_ADDRESS2 IS NOT NULL AND NETMASK IS NOT NULL AND IP4_ADDRESS IS NULL AND AUTHENTICATED_GROUP_NAME IS NULL) OR
                   (AUTHENTICATED_GROUP_NAME IS NOT NULL AND IP4_ADDRESS IS NULL AND IP6_ADDRESS1 IS NULL AND IP6_ADDRESS2 IS NULL AND NETMASK IS NULL)) DEFERRABLE;
ALTER TABLE STOP.COMPANY ADD CONSTRAINT SHORT_LOWERCASE CHECK (lower(short) = short);
ALTER TABLE TT.EVENT_NOTIFICATION ADD CONSTRAINT C_EVENT_NOTIFICATION_1 CHECK ((EVENT_TYPE_GROUP_ID IS NULL AND EVENT_TYPE_ID IS NOT NULL) OR (EVENT_TYPE_GROUP_ID IS NOT NULL AND EVENT_TYPE_ID IS NULL)) DEFERRABLE;
ALTER TABLE TT.EVENT_NOTIFICATION ADD CONSTRAINT C_EVENT_NOTIFICATION_2 CHECK (SERVICE_ID IS NULL OR (TICKET_ID IS NULL AND SERVICE_TYPE_ID IS NULL AND COMPANY_UNIT_ID IS NULL)) DEFERRABLE;
ALTER TABLE TT.EVENT_NOTIFICATION ADD CONSTRAINT C_EVENT_NOTIFICATION_3 CHECK (COMPANY_UNIT_ID IS NULL OR (TICKET_ID IS NULL AND SERVICE_ID IS NULL)) DEFERRABLE;
ALTER TABLE TT.EVENT_NOTIFICATION ADD CONSTRAINT C_EVENT_NOTIFICATION_4 CHECK (SERVICE_TYPE_ID IS NULL OR (TICKET_ID IS NULL AND SERVICE_ID IS NULL)) DEFERRABLE;
ALTER TABLE TT.EVENT_NOTIFICATION ADD CONSTRAINT C_EVENT_NOTIFICATION_5 CHECK (TICKET_ID IS NULL OR (TICKET_TYPE_ID IS NULL AND SERVICE_ID IS NULL AND SERVICE_TYPE_ID IS NULL AND COMPANY_UNIT_ID IS NULL)) DEFERRABLE;
ALTER TABLE TT.EVENT_NOTIFICATION ADD CONSTRAINT C_EVENT_NOTIFICATION_6 CHECK (TICKET_TYPE_ID IS NULL OR TICKET_ID IS NULL) DEFERRABLE;
ALTER TABLE TT.TICKET ADD CONSTRAINT C_TICKET_1 CHECK (MSS_SERVICE_ID IS NOT NULL OR STATUS_ID >= 102 OR HOST_ID IS NULL) DEFERRABLE;
ALTER TABLE TT.TICKET ADD CONSTRAINT C_TICKET_2 CHECK (STATUS_ID != 2 or WORKER_ID IS NOT NULL) DEFERRABLE;
